import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"TiViBench: Benchmarking Think-in-Video Reasoning for Video Generative Models","description":"","frontmatter":{"title":"TiViBench: Benchmarking Think-in-Video Reasoning for Video Generative Models","arxiv":"2511.13704","date":"2025-11-17","authors":"Harold Haodong Chen, Disen Lan, Wen-Jie Shu, Qingyang Liu, Zihan Wang, Sirui Chen, Wenkai Cheng, Kanghao Chen, Hongfei Zhang, Zixin Zhang, Rongjin Guo, Yu Cheng, Ying-Cong Chen","categories":"cs.CV","topics":"物理感知视频生成, 视频推理评测, 测试时优化","outline":[2,2]},"headers":[],"relativePath":"papers/2511.13704.md","filePath":"papers/2511.13704.md","lastUpdated":null}'),e={name:"papers/2511.13704.md"};function l(i,s,r,m,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="tivibench-benchmarking-think-in-video-reasoning-for-video-generative-models" tabindex="-1">TiViBench: Benchmarking Think-in-Video Reasoning for Video Generative Models <a class="header-anchor" href="#tivibench-benchmarking-think-in-video-reasoning-for-video-generative-models" aria-label="Permalink to &quot;TiViBench: Benchmarking Think-in-Video Reasoning for Video Generative Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.13704" target="_blank" rel="noreferrer">2511.13704</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-17</td></tr><tr><td><strong>作者</strong></td><td>Harold Haodong Chen, Disen Lan, Wen-Jie Shu, Qingyang Liu, Zihan Wang, Sirui Chen, Wenkai Cheng, Kanghao Chen, Hongfei Zhang, Zixin Zhang, Rongjin Guo, Yu Cheng, Ying-Cong Chen</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 4 维度 24 场景 595 样本的分层 I2V 基准把「帧链推理」量化成可验证的 Pass@k，并用无需训练的 VideoTPO（双样本自评 → 文本梯度 → 改写 prompt）在测试时把开源模型准确率翻倍。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型的评测长期停留在「好不好看」这一层：VBench 系列量的是时序平滑、主体一致、美学质量，AIGCBench、TC-Bench 量的是与 prompt 的对齐度。这些指标默认视频模型是渲染器。但 Veo 3 展示的 chain-of-frames 让人怀疑它还是别的东西——如果每一帧都可以是一个推理步骤，那么「生成一段视频」就等价于「把思考过程画出来」，视频模型有可能像 LLM 那样解迷宫、填数独、规划工具使用。</p><p>问题在于，没有任何现有 benchmark 能区分「模型真的推理出了迷宫的解」和「模型画了一条看起来像路径的曲线」。TiViBench 要补的正是这个缺口：给 image-to-video 生成建一套<strong>答案可验证</strong>的推理评测。这件事的价值不只是排名。作者把它类比成视频生成的 GPT 时刻判断依据——只有能量化推理深度，才知道当前模型离通用视觉基础模型还差多远，以及差在哪一环。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>I2V 评测方面，VBench++、AIGCBench、TC-Bench 已经把生成质量的多维打分做得相当成熟，但它们的样本只包含一张推理起始图，没有过程状态和目标状态，因此天然无法验证「过程对不对」。WorldScore 这类世界生成评测靠近物理一致性，仍不覆盖符号与逻辑推理。Wiedemer 等人（Video models are zero-shot learners and reasoners）首次系统展示了 Veo 3 在图遍历、迷宫求解上的零样本能力，但那是定性 showcase，任务数量有限、没有难度分级、也没有自动化度量。</p><p>Prompt 优化方面，前人分两类：pre-inference rewriting（Wan、Veo 的官方 prompt 扩写）靠 LLM 补细节，风险是偏离用户意图；post-inference rewriting（PhyT2V、Self-Refine 式）依据生成结果改写 prompt，但都是单次单样本，一轮只产生一个样本、只能给出「这个不好」的粗粒度信号。对于推理任务，候选之间的差别往往非常细微（同一条迷宫路径只错了一个拐角），单样本反馈提供不了足以定位问题的梯度。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个可观察的不对称：LLM 的推理评测之所以能做起来，是因为答案可验证——数学题有唯一解，代码有单元测试。视频生成一直做不了同类评测，因为「一段视频」没有 ground truth。但如果刻意挑选那些<strong>终态可判定</strong>的任务（数独填完了就是一个数字矩阵，迷宫走完了就是一条轨迹），视频就重新变得可验证了。</p><p>第二步是意识到视频比图像多给了一样东西：过程。数独可以只看最后一帧，迷宫却必须看轨迹有没有穿墙。于是度量自然分成两类：final-state validation 与 process-and-goal consistency。既然任务类型各异（有的要 OCR，有的要计数，有的要跟踪），单一裁判模型不够用，只能按任务配专用工具——OpenCV 做网格与 OCR，DINO 做局部语义比对，DINO-X 做开放词表 grounding 与跨帧跟踪，Gemini 做因果性 QA。</p><p>第三步来自测试时优化的类比。LLM 领域的 test-time preference optimization 用多候选之间的偏好比较产生「文本梯度」。视频生成的候选差异更细微，反而更适合成对比较而非打分。这就直接推出了 VideoTPO 的形态。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>推理任务的对错是离散的，所以别再打连续质量分，直接用 Pass@k；而模型之所以在推理任务上失败，很大程度不是「不会」而是「这一次没画对」，所以 Pass@1 与 Pass@5 的落差本身就是最有信息量的指标。既然模型的正确解藏在采样分布里，那么把两个候选摆在一起让 VLM 说出「哪个更接近任务定义、为什么」，就能把这条信息回灌成一个更精确的 prompt，而不需要任何训练。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>benchmark 侧覆盖 4 维度、24 场景、595 个 image-prompt 样本、3 个难度等级：Structural Reasoning &amp; Search（图遍历、迷宫、数字排序、时序排列、规则外推、棋类走子）、Spatial &amp; Visual Pattern Reasoning（形状嵌合、连色、模式识别、找不同、计数、视觉类比）、Symbolic &amp; Logical Reasoning（数独、算术、符号推理、视觉演绎、传递推理、游戏规则）、Action Planning &amp; Task Execution（工具使用、机器人导航、目标规划、多步操作、指令跟随、策略规划）。数据来自网络采集、已有数据集（Video-MMLU 的讲课视频、PhysToolBench 的工具图）与 Python 脚本合成，每个样本同时记录初始状态、过程状态与目标状态。</p><p>以算术题为例：输入图是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[(</span><span class="mord">18</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">6</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">15</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">÷</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">3</span><span class="mclose"><span class="mclose">]</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">25</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span></span></span></span>，目标状态是等号后写上 1631。prompt 由 Gemini-2.5-Pro 依据首末两张图生成叙事式描述（「随着时间推移，解题步骤逐渐出现在题目下方」），刻意不写「请计算」这类指令式措辞，再经三名标注者独立复核，任一人标记不清即返工。生成的视频交给 OpenCV 二值化 + OCR 提取等号后内容，与真值比对。迷宫任务则改用 DINO-X 逐帧 grounding「blue block」得到轨迹，同时校验终点正确与中途未穿墙。</p><p>VideoTPO 侧的流程是：给定图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span> 与 prompt <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，I2V 模型采两条视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0611em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.453em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.453em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>，GPT-4o 对二者做自我分析产出文本 critique（文本损失），再据此产出改写建议（文本梯度），最后更新 prompt。默认宽度 2 样本、深度 2 步。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>VideoTPO 把 TextGrad 的「语言即梯度」搬到视频生成上。设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">M</span></span></span></span> 为 VLM 优化器，三步分别为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1141em;vertical-align:-0.25em;"></span><span class="mord mathcal">M</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0593em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">M</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">M</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0593em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">.</span></span></span></span></span></p><p>三式与一次梯度下降一一对应：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是损失，但它是自然语言的定性批评而非标量；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0593em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是把损失翻译成「该往哪个方向改」的可执行建议；第三式是参数更新，被更新的「参数」是 prompt 本身。与标准 TPO 的差别在于不需要外部 reward model 排序：推理任务的候选差异细微，标量奖励难以区分好坏，而成对自我分析能给出「上面那条没有按升序消失」这种可定位的信号。</p><p>度量侧用 Pass@<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，即 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 次采样中至少一次正确的比例。它比平均分更贴合推理任务的离散性，且 Pass@5 与 Pass@1 的差反映的是能力的<strong>稳定性</strong>而非有无。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>问题一：视频模型到底有没有推理潜力？作者评了 4 个开源模型（CogVideoX1.5-I2V、HunyuanVideo-I2V、Wan2.1-I2V-14B、Wan2.2-I2V-A14B）与 3 个商业模型（Kling 2.1、Veo 3.1-fast、Sora 2）。Pass@1 上 Sora 2 以 27.90% 居首，Veo 3.1 为 26.05%，Kling 2.1 为 11.60%，开源最好的 Wan2.2 只有 9.41%。但 Pass@5 把 Wan2.2 抬到 16.47%、Wan2.1 从 8.40% 抬到 15.29%——开源模型能做对，只是做不稳。作者据此推断能力差距主要来自训练数据规模与多样性，而非架构范式的先天缺陷。</p><p>问题二：失败在哪？细分到 24 个任务后，视觉演绎、指令跟随这类弱依赖严格规则的任务准确率明显更高，而迷宫、时序排列、找不同、数独这类需要显式规则遵守与符号操作的任务崩得最厉害。作者给出两条归因：一是模型无法把 prompt 里的高层约束当作硬性规则（迷宫题明说不得越界，越界照样发生）；二是 VAE 这类编码器对精细符号的压缩过强，推理所需的细节在潜空间里已经丢失。第二条属于基于证据的推断，论文没有做编码器消融来直接证明。</p><p>问题三：测试时优化够不够？VideoTPO 把 HunyuanVideo 从 4.03% 提到 10.25%，把 Wan2.1 从 8.40% 提到 18.15%，都优于 pre-rewriter（Wan2.1 → 10.76%）与 post-rewriter（→ 12.10%）。另一组对照更有意思：把 HunyuanVideo 上优化好的 prompt 直接喂给 Wan2.1（w/ HYV Prompt），提升有限甚至下降，说明优化出来的 prompt 是<strong>模型特异</strong>的，这也反过来证明 VideoTPO 学到的不是通用的写作技巧。宽度（候选数）与深度（迭代步数）扩大时性能持续上升。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p>五句话版：TiViBench 把 I2V 生成的推理能力拆成结构搜索、空间模式、符号逻辑、动作规划四个维度共 24 个场景 595 个样本，并按三档难度分级；它的关键设计是只挑终态可自动验证的任务，从而用 OpenCV / DINO / DINO-X / Gemini 组成的任务专用度量替代单一裁判；评测显示商业模型（Sora 2 27.90%、Veo 3.1 26.05%）显著领先开源模型（Wan2.2 9.41%），但开源模型 Pass@5 大幅高于 Pass@1，说明潜力存在而稳定性不足；失败集中在需要显式规则遵守与符号精度的任务上；VideoTPO 用双候选自我分析构造文本损失与文本梯度迭代改写 prompt，无需训练即把 Wan2.1 从 8.40% 提到 18.15%。</p><p>三句话版：视频生成的推理能力此前只有定性 showcase，TiViBench 用可验证任务把它变成 Pass@k 数字。结果是商业模型领先、开源模型「会但不稳」，失败集中在规则遵守与符号精度两处。VideoTPO 证明这部分潜力可以在测试时用 prompt 偏好优化廉价地释放出来。</p><p>一句话版：把视频模型的「思考」变成可打分的东西，然后发现分数还很低、但用改 prompt 就能翻倍。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>帧链的正确终态等价于推理正确</strong>。TiViBench 的大部分度量是 final-state validation，只有迷宫、序列消除等少数任务上了 DINO-X 跟踪做过程校验。一旦模型学会了「猜答案再画上去」——例如直接在数独空格里渲染出正确数字，而中间帧完全没有逐格填写的推演——benchmark 会判它通过，而它其实没有做任何逐帧推理。这不是空想：同期的 V-ReasonBench 就明确记录了「终态对、过程错」的现象（迷宫里老鼠穿墙到达终点）。</p><p>论文提供的正面证据是 Sora 2 数独案例：模型用「?」当占位符、再让数字「移动」到正确格子，这种类人过程暗示它确实在模拟解题过程。但这是单个定性观察，无法支撑全 benchmark 的假设。缺的证据是过程级度量在多少比例任务上被真正执行，以及在这些任务上过程分与终态分的相关性有多高。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证针对 §9 的假设，不需要复现完整 benchmark。选 TiViBench 的数独与算术两类共约 40 个样本（终态可 OCR），用一个开源模型（Wan2.1-I2V-14B 或 CogVideoX1.5）各采 5 条视频。实现两件事：一是复用论文的 OpenCV 终态判分；二是自己加一个廉价的过程判分——对数独，逐帧 OCR 统计已填格子数随时间的单调性；对算术，统计等号后字符首次出现的帧号并检查其后是否稳定不变。</p><p>测量：在所有终态判为「通过」的样本里，过程分合格（填格数单调不减、答案出现后不再改动）的比例 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.8</span></span></span></span>，说明终态验证基本能代表过程正确，论文假设站得住；若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span>，说明大量通过样本是「跳答案」，Pass@k 高估了推理能力。再加一个对照：把同一批题喂给一个图像生成模型（如 NanoBanana 类）只出一张终态图，如果它的终态通过率与视频模型相当，那视频这一模态在这些任务上并没有带来推理增益。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释攻击：TiViBench 的 prompt 由 Gemini-2.5-Pro 依据<strong>初始图和目标图</strong>共同生成。即便刻意做了「不透露解法路径」的约束，目标图仍然是 prompt 作者见过的。叙事式描述极易在无意中泄漏答案的形状——「随着时间推移，方块沿着白色路径平滑滑行，停在红点处」已经把终点说了。如果是这样，模型的高分反映的是<strong>指令跟随</strong>能力而非推理能力，而 VideoTPO 的增益就更可疑：它做的可能只是把泄漏得不够明显的 prompt 改写得更明确（论文自己给出的优化后 prompt 案例里，确实出现了「每秒一个数字依次出现在每个形状正上方」这种把任务规格写死的改写）。</p><p>具体实验：构造 prompt 的消融版本——用<strong>只看初始图</strong>的 prompt（作者无法看到目标状态）重跑 Sora 2 与 Wan2.1。如果分数大幅下降，说明原 prompt 存在答案泄漏，排行榜衡量的成分需要重新解释；如果基本持平，则论文的 claim 得到加强。这个实验成本不高但结论很硬。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动局限：TiViBench 与 VideoTPO 都把 prompt 当成唯一可优化的接口，而 §7 的跨模型迁移失败恰恰说明，被优化的其实是「如何把任务翻译成这个模型听得懂的话」，而不是模型的推理能力本身。这条路的天花板是模型已有的能力上限。</p><p>新的 framing：不优化 prompt，而是<strong>优化推理的时间分配</strong>。把 chain-of-frames 类比成 LLM 的 token 预算，但视频模型的「思考长度」目前是由用户设定的秒数外生决定的，模型无法自己决定某一步该慢下来。可借鉴的相邻工具是自适应计算（adaptive computation time）与推测解码：让模型在潜空间里为每个子步骤预测一个「需要多少帧」的预算，把帧数当作可学习的资源分配。V-ReasonBench 观察到的「时长变长反而更差」正说明均匀分配帧数是错的。</p><p>第一个实验：在一个可控任务（迷宫）上，把 41 帧的预算改成由外部规划器按拐点数量分配（直线段少给帧、拐弯处多给帧），用现成的轨迹条件生成器（如 ATI）实现，比较均匀分配与非均匀分配下的过程正确率。若非均匀分配显著更好，则说明「思考时间」是视频推理里一个未被利用的自由度，值得做成端到端可学习的模块。</p>',45)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
